                <path d="M65.4138 56.0667L63.7653 59.501C63.608 59.8287 63.2298 59.989 62.8883 59.8645C59.3248 58.5653 57.4073 56.835 56.7852 55.842C56.6784 55.6715 56.6819 55.4602 56.7626 55.2759L57.7187 53.0903C57.8289 52.8386 58.0732 52.6691 58.348 52.668C61.6544 52.6553 63.9474 54.1819 65.227 55.2107C65.4825 55.4162 65.5556 55.7712 65.4138 56.0667Z" fill="#B3B3B3" />
