// Each "digit" pulls the dial clockwise to the finger stop, holds, then lets it spin back.
// Bigger angle = digit further from the stop, so it takes longer both ways (like a real dial).
const DIAL_ANGLES = [120, 60, 150, 90];
const DIAL_HOLD = 0.12;
const DIAL_GAP = 0.3;
const IDLE_START_DELAY = 2;
const IDLE_REPEAT_DELAY = 4;

const buildDialKeyframes = () => {
    const rotations = [0];
    const stamps = [0];
    const eases: Easing[] = [];
    let t = 0;

    DIAL_ANGLES.forEach((angle) => {
        // [rotation, duration, ease]: pull -> hold -> release -> gap
        const steps: [number, number, Easing][] = [
            [angle, 0.2 + angle / 450, easeInOut],
            [angle, DIAL_HOLD, "linear"],
            [0, 0.15 + angle / 600, easeOut],
            [0, DIAL_GAP, "linear"],
        ];
        steps.forEach(([rotation, duration, ease]) => {
            t += duration;
            rotations.push(rotation);
            stamps.push(t);
            eases.push(ease);
        });
    });

    return {
        transform: rotations.map((r) => `rotate(${r}deg)`),
        times: stamps.map((s) => s / t),
        ease: eases,
        duration: t,
    };
};

const dial = buildDialKeyframes();

const dialIdle = (delay: number) => ({
    transform: dial.transform,
    transition: {
        duration: dial.duration,
        times: dial.times,
        ease: dial.ease,
        delay,
        repeat: Infinity,
        repeatType: "loop",
        repeatDelay: IDLE_REPEAT_DELAY
    }
});

const numbersVrnt = {
    initial: {
        transform: "rotate(0deg)",
        transition: {
            duration: 0.3,
            ease: easeOut
        }
    },
    idle: dialIdle(IDLE_START_DELAY),
    // Back off a bit after the cursor leaves before dialing again
    idleAfterHover: dialIdle(IDLE_REPEAT_DELAY / 2),
}

